#!/usr/bin/env python3
"""Independent CPU predictions plus human-review-gated metrics; production code stays unchanged."""
import argparse,copy,hashlib,json,statistics,sys,time
from datetime import datetime,timezone
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[1]))
from backend.independent_inference import IndependentDetector
from evaluation.metrics import evaluate_detections,intersection_over_union


def digest(path):
    h=hashlib.sha256()
    with path.open('rb') as handle:
        for chunk in iter(lambda:handle.read(1024*1024),b''):h.update(chunk)
    return h.hexdigest()


def load_review(manifest,annotations):
    """Human attestation is supplied by the operator, never generated by predictions."""
    if annotations.get('dataset_id')!=manifest['dataset_id'] or annotations.get('source_video_sha256')!=manifest['source_video_sha256']:raise ValueError('Annotation/source mismatch')
    images=copy.deepcopy(annotations['images'])
    if [i['image_id'] for i in images]!=[i['image_id'] for i in manifest['images']]:raise ValueError('Annotation image IDs/order must match the dataset')
    for item,expected in zip(images,manifest['images']):
        if any(item.get(k)!=expected[k] for k in ('width','height','image_sha256')):raise ValueError('Annotation image hash/dimensions mismatch')
    record=annotations.get('human_review_record',{})
    complete=record.get('complete') is True and record.get('status')=='HUMAN_REVIEW_COMPLETE' and bool(record.get('reviewer_name')) and record.get('method')=='human_manual_boxes_without_predictions' and record.get('model_predictions_used_as_ground_truth') is False
    accepted=complete and all(i.get('reviewed_by_human') is True and i.get('reviewed_by') and i.get('reviewed_at') and i.get('annotation_source')=='human_manual' for i in images)
    # Partial labels may be retained for review, but never silently become empty negatives.
    if not accepted:
        for image in images:image['reviewed_by_human']=False
    return images,accepted,record


def render_comparison(image_path,image,predictions,path,reviewed,threshold=.5):
    from PIL import Image,ImageDraw
    source=Image.open(image_path).convert('RGB');draw=ImageDraw.Draw(source)
    def box(item,color,text):
        a,b,c,d=item['bbox'];coords=[a*source.width,b*source.height,c*source.width,d*source.height]
        draw.rectangle(coords,outline=color,width=2);draw.text((coords[0],max(16,coords[1]-12)),text,fill=color)
    kept=sorted((p for p in predictions if p['confidence']>=threshold),key=lambda p:-p['confidence']);truth=image['ground_truth'];matched=set()
    for prediction in kept:
        if reviewed:
            available=[(intersection_over_union(prediction['bbox'],g['bbox']),n) for n,g in enumerate(truth) if n not in matched]
            best=max(available,default=(0.,-1));hit=best[0]>=.5
            if hit:matched.add(best[1])
            box(prediction,'lime' if hit else 'red',f"{'TP' if hit else 'FP'} {prediction['confidence']:.2f}")
        else:box(prediction,'orange',f"Unverified prediction {prediction['confidence']:.2f}")
    if reviewed:
        for n,g in enumerate(truth):box(g,'cyan' if n in matched else 'blue','Human GT' if n in matched else 'Missed human GT')
    draw.rectangle([0,0,source.width,18],fill='black');draw.text((5,3),'Human reviewed GT + AI, IoU0.5/conf0.5' if reviewed else 'HUMAN GT PENDING — predictions are not verified person labels',fill='white')
    path.parent.mkdir(parents=True,exist_ok=True);source.save(path)


def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--dataset',required=True,type=Path);parser.add_argument('--model',required=True,type=Path);parser.add_argument('--dependencies',required=True)
    parser.add_argument('--report-dir',required=True,type=Path);parser.add_argument('--annotations',type=Path);parser.add_argument('--reuse-predictions',action='store_true')
    args=parser.parse_args();dataset=args.dataset.resolve(strict=True);manifest=json.loads((dataset/'dataset-manifest.json').read_text());annotation_path=args.annotations or dataset/'annotations.json';annotations=json.loads(annotation_path.read_text());images,approved,review_record=load_review(manifest,annotations)
    args.report_dir.mkdir(parents=True,exist_ok=True)
    worker=IndependentDetector(args.model,args.dependencies,confidence=0.0);status=worker.status()
    if not status['available']:raise SystemExit('Actual CPU inference unavailable; no fabricated prediction fallback')
    if status['model_sha256']!='8db1e3bb5e53410eb79da1e166fa3e1a05d6d1ff29df33af7345f2f3b73e20d7':raise SystemExit('Evaluate the preserved original model first; unexpected model hash')
    records=[];latencies=[];prediction_path=args.report_dir/'predictions.json'
    if args.reuse_predictions:
        saved=json.loads(prediction_path.read_text())
        if saved['source_video_sha256']!=manifest['source_video_sha256'] or saved['model_sha256']!=status['model_sha256'] or saved['image_hashes']!={i['image_id']:i['image_sha256'] for i in manifest['images']}:raise ValueError('Stored predictions belong to a different source/model/images')
        records=saved['predictions'];latencies=saved['processing_latency_ms']
    else:
        if prediction_path.exists():raise SystemExit('Predictions already exist; use --reuse-predictions for the same recorded outputs')
        for image in manifest['images']:
            relative=Path(image['path']);path=(dataset/relative).resolve(strict=True)
            if relative.is_absolute() or dataset not in path.parents or digest(path)!=image['image_sha256']:raise ValueError('Frame path/hash mismatch')
            result=worker.detect(path.read_bytes())
            if result['width']!=image['width'] or result['height']!=image['height']:raise ValueError('Unexpected frame dimensions')
            latencies.append(result['processing_latency_ms'])
            records.extend(dict(image_id=image['image_id'],**d) for d in result['detections'])
            print(f"Inferred {image['image_id']}: {sum(d['confidence']>=.5 for d in result['detections'])} predictions at0.5; {result['processing_latency_ms']:.1f}ms",flush=True)
        prediction_path.write_text(json.dumps(dict(dataset_id=manifest['dataset_id'],source_video_sha256=manifest['source_video_sha256'],model_sha256=status['model_sha256'],image_hashes={i['image_id']:i['image_sha256'] for i in manifest['images']},predictions=records,processing_latency_ms=latencies),indent=2)+'\n')
    result=evaluate_detections(images,records)
    result.update(experiment_date=datetime.now(timezone.utc).isoformat(),dataset_id=manifest['dataset_id'],source_video_sha256=manifest['source_video_sha256'],model=status,images_evaluated=len(images),independently_human_reviewed_images=sum(i.get('reviewed_by_human') is True for i in annotations['images']),human_review_record_accepted=approved,human_review_record=review_record,annotation_file_sha256=digest(annotation_path),prediction_file_sha256=digest(prediction_path),model_preprocessing_unchanged=True,production_confidence_threshold_unchanged=True,processing_latency_ms={'min':min(latencies),'median':statistics.median(latencies),'max':max(latencies)},evaluation_limits=['Single short moving-camera source, no deployment generalization','Detector outputs capped at100 NMS0.45 person candidates perframe;AP conditional on these bounded outputs','Review boxes cover visible extents, not hidden full bodies','No crowd/ignore/area-ranges or full COCO benchmark semantics','CPU processing is not PipeGen TensorRT FP16 speed evidence'])
    (args.report_dir/'independent-detection-evaluation.json').write_text(json.dumps(result,indent=2)+'\n')
    study=dict(status=result['status'],human_review_record_accepted=approved,confidence_thresholds=result['thresholds'],precision_recall_f1_available=result['formal_metrics_available'],recommendation='Retain existing production0.50; do not tune on unreviewed predictions' if not approved else 'Review measured precision/recall safety trade-offs before any separately approved production change',production_threshold_changed=False,detection_rejection_is_not_false_positive_count=True,limitations=result['evaluation_limits'])
    (args.report_dir/'threshold-study.json').write_text(json.dumps(study,indent=2)+'\n')
    (args.report_dir/'human-review-record.json').write_text(json.dumps(dict(record=review_record,accepted=approved,annotation_file_sha256=digest(annotation_path),independently_human_reviewed_images=result['independently_human_reviewed_images']),indent=2)+'\n')
    # Qualitative sheets never invent TP/FP/FN without approved human labels.
    by_image={i['image_id']:[] for i in manifest['images']}
    for item in records:by_image[item['image_id']].append(item)
    for image,review in zip(manifest['images'],images):
        if image['frame_index'] in [0,106,253]:render_comparison(dataset/image['path'],review,by_image[image['image_id']],args.report_dir/'comparisons'/f"frame-{image['frame_index']:03}.png",approved)
    report=f"# Independent detection evaluation\n\nStatus: {result['status']}. Human-reviewed images: {result['independently_human_reviewed_images']}/{len(images)}. Formalmetrics available: {result['formal_metrics_available']}.\n\nThe same bounded model outputs are filtered at0.25/0.40/0.50/0.60/0.70. Rejected detections do not establish false positives or missed-person risks without reviewed GT. Keep production0.50 unchanged.\n\nOne short moving-camera warehouse clip cannot establish deployment accuracy. Partial review is not treated as negative labels. CPU timings are not TensorRT or PipeGen bonus evidence.\n"
    (args.report_dir/'evaluation-summary.md').write_text(report)
    print(f"Evaluation status: {result['status']}; formal accuracy available: {result['formal_metrics_available']}")


if __name__=='__main__':main()
